package net.officefloor.hq.app.holiday;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Records a holiday added: HOLIDAY_ADDED sheet=<id> by=<user> date=<date>. */
public class AuditHolidayAdded {
    public void audit(@PathVariable("sheetId") String sheetId, @Val HolidayInput holiday, Audit audit) {
        audit.record("HOLIDAY_ADDED sheet=" + sheetId.trim() + " by=" + holiday.user() + " date=" + holiday.date());
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;

/** A holiday to add, validated, and the user adding it. */
public record HolidayInput(LocalDate date, String user) {
}
package net.officefloor.hq.app.holiday;

/** Body of POST /api/sheets/{sheetId}/holidays: the date (yyyy-mm-dd) and the user who adds it. */
public record HolidayRequest(String date, String user) {
}
package net.officefloor.hq.app.holiday;

/** A holiday as the front end reads it: its date (yyyy-mm-dd). */
public record HolidayResponse(String date) {
}
package net.officefloor.hq.app.holiday;

import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.history.History;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The holidays per sheet. A claim's due-by, fixed when it is added, counts business days past those on the
 *  sheet then (see {@link #businessDaysAfter}); a holiday added later leaves existing due-by dates as they are. */
@Repository
public class HolidayStore {

    private final JdbcTemplate jdbc;

    public HolidayStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's holidays, earliest first. */
    public List<LocalDate> list(String sheetId) {
        return jdbc.queryForList("SELECT holiday_date FROM holiday WHERE sheet_id = ? ORDER BY holiday_date",
                LocalDate.class, sheetId);
    }

    /** The sheet's holidays at the end of the date (see {@link History}), earliest first. */
    public List<LocalDate> listAsOf(String sheetId, LocalDate date) {
        return jdbc.queryForList("SELECT holiday_date FROM " + History.asOf("holiday", "id", date)
                + " WHERE sheet_id = ? ORDER BY holiday_date", LocalDate.class, sheetId);
    }

    public boolean has(String sheetId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM holiday WHERE sheet_id = ? AND holiday_date = ?",
                Integer.class, sheetId, date);
        return n != null && n > 0;
    }

    public void add(String sheetId, LocalDate date) {
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) VALUES (?, ?)", sheetId, date);
    }

    /** The {@code days}-th business day after the date: counting forward from the day after it, skipping every
     *  Saturday, Sunday and holiday on the sheet now. The date itself when {@code days} is 0. */
    public LocalDate businessDaysAfter(String sheetId, LocalDate date, int days) {
        return businessDaysAfter(new HashSet<>(list(sheetId)), date, days);
    }

    /** The {@code days}-th business day after the date, skipping weekends and the given holidays. */
    public static LocalDate businessDaysAfter(Set<LocalDate> holidays, LocalDate date, int days) {
        LocalDate d = date;
        for (int n = 0; n < days; ) {
            d = d.plusDays(1);
            if (isBusinessDay(holidays, d)) {
                n++;
            }
        }
        return d;
    }

    private static boolean isBusinessDay(Set<LocalDate> holidays, LocalDate d) {
        DayOfWeek day = d.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !holidays.contains(d);
    }
}
package net.officefloor.hq.app.holiday;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithHoliday {
    public void respond(@Val HolidayInput holiday, ObjectResponse<HolidayResponse> response) {
        response.send(new HolidayResponse(holiday.date().toString()));
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.history.History;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class RespondWithHolidays {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, HolidayStore store,
            ObjectResponse<List<HolidayResponse>> response) {
        LocalDate on = History.date(asOf);
        response.send((on == null ? store.list(sheetId.trim()) : store.listAsOf(sheetId.trim(), on)).stream()
                .map(d -> new HolidayResponse(d.toString())).toList());
    }
}
package net.officefloor.hq.app.holiday;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveHoliday {
    public void save(@PathVariable("sheetId") String sheetId, @Val HolidayInput holiday, HolidayStore store) {
        store.add(sheetId.trim(), holiday.date());
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a holiday by a viewer, without a yyyy-mm-dd date, or on a date already on the sheet's list. */
public class ValidateHoliday {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody HolidayRequest request,
            Out<HolidayInput> body, RoleStore roles, HolidayStore holidays) throws InvalidSheetException {
        String sheet = sheetId.trim();
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheet, user);
        String text = request == null || request.date() == null ? "" : request.date().trim();
        if (text.isEmpty()) {
            throw new InvalidSheetException("A date is required");
        }
        LocalDate date;
        try {
            date = LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("The date must be a date (yyyy-mm-dd)");
        }
        if (holidays.has(sheet, date)) {
            throw new InvalidSheetException(date + " is already a holiday");
        }
        body.set(new HolidayInput(date, user));
    }
}
-- The sheet's holidays: a claim's due-by, when fixed at creation, is moved past any of them. Each date at
-- most once per sheet; the id orders them as they were added. Kept by version like the rest of the screen.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(255) NOT NULL,
    holiday_date DATE         NOT NULL,
    UNIQUE (sheet_id, holiday_date)
);

CREATE TABLE holiday_hist AS SELECT * FROM holiday WITH NO DATA;
