import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet } from '../../session/session';
import { STATUSES, isActive, live, statusCount, useClaims } from '../claims/claims';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { dueTotal, personDue, useRates } from '../rates/rates';
import { floorOf, useSettings } from '../settings/settings';
import { useSheetToday } from '../sheet/sheet';
import { lateOf } from '../overdue/overdue';

// The sheet at a glance, worked out from the same figures the lists show: per grade, the people on it
// today (retired people excluded), their due-totals added up (skipping n/a) and how many of them are
// active; per period, its due-total; per status, how many claims have it.
function Summary() {
  const [sheet] = useCurrentSheet();
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const periods = usePeriods(sheet);
  const rates = useRates(sheet);
  const today = useSheetToday(sheet);
  const settings = useSettings(sheet).data;
  const floor = floorOf(settings);
  const late = lateOf(settings, today, people.data);

  const active = (people.data ?? []).filter((p) => !p.retired);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p.grades, today) === grade);
  const dueOf = (p: (typeof active)[number]) =>
    personDue(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), rates.data, p.grades, today, floor, late, settings?.cap);

  const isActiveOn = (p: (typeof active)[number]) =>
    isActive(live((claims.data ?? []).filter((c) => c.personId === p.id), [p]), today);

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`summary-grade-${g}-count`}>{onGrade(g).length}</td>
              <td data-testid={`summary-grade-${g}-due-total`}>{dueTotal(onGrade(g).map(dueOf))}</td>
              <td data-testid={`summary-grade-${g}-active`}>{onGrade(g).filter(isActiveOn).length}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>
                {periodDue(p, claims.data, people.data, rates.data, floor, late)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{statusCount(claims.data, s)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 46, Component: Summary });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../../session/session';
import { type Holiday, holidaysKey, useHolidays } from './holidays';

// The sheet's holidays, and the entry a date is added with. A date already on the list is refused.
function Holidays() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const holidays = useHolidays(sheet);
  const [date, setDate] = useState('');
  const queryClient = useQueryClient();

  const add = useMutation({
    mutationFn: (d: string) =>
      postJson<Holiday>(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, { date: d, user }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: holidaysKey(sheet) });
      setDate('');
    },
  });
  const submit = useSubmitOnce(add);

  return (
    <section data-testid="holidays">
      <h2>Holidays</h2>
      <ul>
        {(holidays.data ?? []).map((h) => (
          <li key={h.date} data-testid={`holiday-row-${h.date}`}>
            {h.date}
          </li>
        ))}
      </ul>
      <form
        data-testid="holiday-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit(date);
        }}
      >
        <input
          data-testid="holiday-date"
          placeholder="Date (yyyy-mm-dd)"
          value={date}
          onChange={(e) => {
            setDate(e.target.value);
            add.reset();
          }}
        />
        <button type="submit" data-testid="holiday-add" disabled={add.isPending}>
          Add holiday
        </button>
        {add.isError && (
          <span data-testid="holiday-error" role="alert">
            {' '}
            {add.error instanceof HttpError && add.error.reason ? `${add.error.reason}.` : 'The holiday was refused.'}
          </span>
        )}
      </form>
    </section>
  );
}

export const contribution = HomeMain.fill({ order: 47, Component: Holidays });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, sheetKey } from '../sheet/sheet';
import { useAsOf } from '../../session/session';

/** A holiday on the sheet (yyyy-mm-dd). A claim's due-by, fixed when it is added, counts business days
 *  past the weekends and those on the sheet then. */
export type Holiday = { date: string };

/** Under the sheet's key, so loading the sheet again re-reads its holidays. */
export const holidaysKey = (sheet: string) => [...sheetKey(sheet), 'holidays'] as const;

export function useHolidays(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(holidaysKey(sheet), asOf),
    queryFn: () => getJson<Holiday[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/holidays`, asOf)),
    enabled: sheet !== '',
  });
}
import { defineSlot } from '../Slot';

/** The home page's body: the sheet's panels (its people, ...). */
export const HomeMain = defineSlot('home.main');
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
